//! Unit tests. Signatures here come from a local test key (`mock_mpc_response`), standing in for v1.signer
//! inside tests only (S-05). Reference vectors are generated by `pnpm gen:vectors` (viem + live v1.signer).

use super::*;
use k256::ecdsa::SigningKey;
use near_parameters::RuntimeFeesConfig;
use near_sdk::test_utils::VMContextBuilder;
use near_sdk::{test_vm_config, testing_env, PromiseResult};

const TX_VECTORS: &str = include_str!("../tests/vectors/title_tx.json");
const ADDR_VECTORS: &str = include_str!("../tests/vectors/derived_address.json");

fn owner() -> AccountId {
    "tradelock.samuelowen.testnet".parse().unwrap()
}
fn stranger() -> AccountId {
    "mallory.near".parse().unwrap()
}

fn config() -> Config {
    Config {
        mpc_contract: "v1.signer-prod.testnet".parse().unwrap(),
        path: "tradelock/proof/0".into(),
        chain_id: 11155111,
        title_escrow: "0x3781bd0bbd15bf5e45c7296115821933d47362be".into(),
        destination: "0x00000000000000000000000000000000000000b0".into(),
        mpc_sign_deposit: U128(1),
        mpc_sign_gas_tgas: 15,
        callback_gas_tgas: 10,
        max_fee_per_gas: U128(200_000_000_000),
        max_priority_fee_per_gas: U128(20_000_000_000),
        max_gas_limit: U64(500_000),
    }
}

fn ctx(predecessor: AccountId, deposit: u128, gas_tgas: u64) -> VMContextBuilder {
    let mut b = VMContextBuilder::new();
    b.current_account_id(owner())
        .predecessor_account_id(predecessor)
        .attached_deposit(NearToken::from_yoctonear(deposit))
        .prepaid_gas(Gas::from_tgas(gas_tgas));
    b
}

fn set_env(predecessor: AccountId, deposit: u128, gas_tgas: u64) {
    testing_env!(ctx(predecessor, deposit, gas_tgas).build());
}

fn set_callback_env(result: PromiseResult) {
    let mut b = ctx(owner(), 0, 300);
    b.predecessor_account_id(owner()); // #[private]: predecessor == current account
    testing_env!(b.build(), test_vm_config(), RuntimeFeesConfig::test(), Default::default(), vec![result]);
}

fn test_key(seed: u8) -> SigningKey {
    SigningKey::from_bytes(&[seed; 32].into()).unwrap()
}

/// EVM address of a k256 key, computed independently of the contract (via the uncompressed point).
fn key_address(k: &SigningKey) -> Address {
    let point = k.verifying_key().to_encoded_point(false);
    let h = env::keccak256_array(&point.as_bytes()[1..]);
    h[12..].try_into().unwrap()
}

/// v1.signer-shaped response (DECISIONS V-01) signed by a local key. Test-only stand-in for the MPC.
fn mock_mpc_response(k: &SigningKey, payload: &[u8; 32]) -> Vec<u8> {
    let (sig, recid) = k.sign_prehash_recoverable(payload).unwrap();
    let bytes = sig.to_bytes();
    let mut big_r = vec![2 + recid.is_y_odd() as u8];
    big_r.extend_from_slice(&bytes[..32]);
    serde_json::json!({
        "scheme": "Secp256k1",
        "big_r": { "affine_point": hex::encode(big_r) },
        "s": { "scalar": hex::encode(&bytes[32..]) },
        "recovery_id": recid.to_byte(),
    })
    .to_string()
    .into_bytes()
}

fn new_contract() -> TitleProof {
    set_env(owner(), 0, 300);
    TitleProof::new(owner(), config())
}

fn contract_with_derived(k: &SigningKey) -> TitleProof {
    let mut c = new_contract();
    c.derived_address = Some(key_address(k));
    c
}

fn request(c: &mut TitleProof, nonce: u64) -> StoredTx {
    set_env(owner(), 1, 300);
    let _ = c.request_signature(U64(nonce), U128(30_000_000_000), U128(1_500_000_000), U64(120_000));
    match &c.leg {
        Leg::SignatureRequested { tx } => tx.clone(),
        other => panic!("expected SignatureRequested, got {other:?}"),
    }
}

// ---------- reference vectors ----------

#[test]
fn tx_payload_matches_viem_vectors() {
    let v: serde_json::Value = serde_json::from_str(TX_VECTORS).unwrap();
    let vectors = v["vectors"].as_array().unwrap();
    assert!(vectors.len() >= 3);
    set_env(owner(), 0, 300);
    for t in vectors {
        let name = t["name"].as_str().unwrap();
        let tx = build_title_tx(
            t["chain_id"].as_u64().unwrap(),
            t["nonce"].as_str().unwrap().parse().unwrap(),
            t["max_fee_per_gas"].as_str().unwrap().parse().unwrap(),
            t["max_priority_fee_per_gas"].as_str().unwrap().parse().unwrap(),
            t["gas_limit"].as_str().unwrap().parse().unwrap(),
            parse_address(t["to"].as_str().unwrap()).unwrap(),
            parse_address(t["destination"].as_str().unwrap()).unwrap(),
        );
        assert_eq!(to_hex(&tx.data), t["data"].as_str().unwrap(), "{name}: calldata vs TradeTrust ABI encoding");
        assert_eq!(to_hex(&tx.fields().unsigned_bytes()), t["unsigned_tx"].as_str().unwrap(), "{name}: unsigned tx");
        assert_eq!(to_hex(&tx.payload), t["payload"].as_str().unwrap(), "{name}: payload");
    }
}

#[test]
fn derived_address_matches_chainsig_and_v1_signer_vectors() {
    let v: serde_json::Value = serde_json::from_str(ADDR_VECTORS).unwrap();
    set_env(owner(), 0, 300);
    for t in v["vectors"].as_array().unwrap() {
        let got = address::evm_address_from_naj(t["derived_public_key"].as_str().unwrap(), keccak).unwrap();
        assert_eq!(to_hex(&got), t["address"].as_str().unwrap(), "{}/{}", t["predecessor"], t["path"]);
    }
}

#[test]
fn on_derived_public_key_stores_address_from_v1_signer_response() {
    let v: serde_json::Value = serde_json::from_str(ADDR_VECTORS).unwrap();
    let t = v["vectors"]
        .as_array()
        .unwrap()
        .iter()
        .find(|t| t["predecessor"] == "tradelock.samuelowen.testnet" && t["path"] == "tradelock/proof/0")
        .unwrap();
    let mut c = new_contract();
    let raw = serde_json::to_vec(t["derived_public_key"].as_str().unwrap()).unwrap();
    set_callback_env(PromiseResult::Successful(raw.clone()));
    let ret = c.on_derived_public_key(Ok(t["derived_public_key"].as_str().unwrap().to_string()));
    assert_eq!(ret, t["address"].as_str().unwrap());
    assert_eq!(c.get_derived_address().unwrap(), t["address"].as_str().unwrap());
    // Idempotent: same key again is fine.
    set_callback_env(PromiseResult::Successful(raw));
    c.on_derived_public_key(Ok(t["derived_public_key"].as_str().unwrap().to_string()));
}

#[test]
#[should_panic(expected = "derived address changed")]
fn on_derived_public_key_refuses_changed_key() {
    let v: serde_json::Value = serde_json::from_str(ADDR_VECTORS).unwrap();
    let keys: Vec<String> = v["vectors"].as_array().unwrap().iter().map(|t| t["derived_public_key"].as_str().unwrap().to_string()).collect();
    let mut c = new_contract();
    set_callback_env(PromiseResult::Successful(vec![]));
    c.on_derived_public_key(Ok(keys[0].clone()));
    c.on_derived_public_key(Ok(keys[1].clone()));
}

#[test]
#[should_panic(expected = "derived_public_key call failed")]
fn on_derived_public_key_failed_call_panics_without_storing() {
    let mut c = new_contract();
    set_callback_env(PromiseResult::Failed);
    c.on_derived_public_key(Err(PromiseError::Failed));
}

