#[test]
fn request_builds_tx_from_stored_fields_only() {
    let mut c = contract_with_derived(&test_key(1));
    let tx = request(&mut c, 5);
    let cfg = config();
    assert_eq!(tx.to, parse_address(&cfg.title_escrow).unwrap());
    let dest = parse_address(&cfg.destination).unwrap();
    assert_eq!(tx.data, tradetrust::transfer_owners(&dest, &dest));
    assert_eq!(tx.chain_id, 11155111);
    assert_eq!(tx.nonce, 5);
    assert_eq!(tx.payload, keccak(&tx.fields().unsigned_bytes()));
}

// ---------- on_signature ----------

#[test]
fn signature_from_derived_key_is_stored() {
    let k = test_key(7);
    let mut c = contract_with_derived(&k);
    let tx = request(&mut c, 0);
    let resp = mock_mpc_response(&k, &tx.payload);
    set_callback_env(PromiseResult::Successful(resp.clone()));
    let v: serde_json::Value = serde_json::from_slice(&resp).unwrap();
    assert!(c.on_signature(U64(0), Ok(v)));
    match c.get_leg() {
        LegView::Signed { tx: view, signature } => {
            assert_eq!(view.payload, to_hex(&tx.payload));
            assert!(signature.y_parity <= 1);
            assert_eq!(signature.r.len(), 66);
        }
        _ => panic!("expected Signed"),
    }
}

#[test]
fn signature_from_other_key_is_rejected_and_leg_reset() {
    let mut c = contract_with_derived(&test_key(7));
    let tx = request(&mut c, 0);
    let resp = mock_mpc_response(&test_key(8), &tx.payload);
    set_callback_env(PromiseResult::Successful(resp.clone()));
    assert!(!c.on_signature(U64(0), Ok(serde_json::from_slice(&resp).unwrap())));
    assert_eq!(c.leg, Leg::Idle);
}

#[test]
fn high_s_signature_is_rejected() {
    let k = test_key(7);
    let mut c = contract_with_derived(&k);
    let tx = request(&mut c, 0);
    let (sig, recid) = k.sign_prehash_recoverable(&tx.payload).unwrap();
    // Flip to the high-s twin (same signer, malleable form). Ethereum (EIP-2) rejects it; so must we.
    let s_high = -*sig.s();
    let mut big_r = vec![2u8];
    big_r.extend_from_slice(&sig.r().to_bytes());
    let resp = serde_json::json!({
        "scheme": "Secp256k1",
        "big_r": { "affine_point": hex::encode(big_r) },
        "s": { "scalar": hex::encode(s_high.to_bytes()) },
        "recovery_id": recid.to_byte() ^ 1,
    });
    set_callback_env(PromiseResult::Successful(resp.to_string().into_bytes()));
    assert!(!c.on_signature(U64(0), Ok(resp)));
    assert_eq!(c.leg, Leg::Idle);
}

#[test]
fn failed_or_malformed_mpc_response_resets_leg() {
    let k = test_key(7);
    let mut c = contract_with_derived(&k);
    request(&mut c, 0);
    set_callback_env(PromiseResult::Failed);
    assert!(!c.on_signature(U64(0), Err(PromiseError::Failed)));
    assert_eq!(c.leg, Leg::Idle);

    request(&mut c, 0);
    let bad = serde_json::json!({ "scheme": "Ed25519", "signature": [] });
    set_callback_env(PromiseResult::Successful(bad.to_string().into_bytes()));
    assert!(!c.on_signature(U64(0), Ok(bad)));
    assert_eq!(c.leg, Leg::Idle);
}

#[test]
fn stale_callback_with_other_nonce_is_ignored() {
    let k = test_key(7);
    let mut c = contract_with_derived(&k);
    let tx = request(&mut c, 3);
    let resp = mock_mpc_response(&k, &tx.payload);
    set_callback_env(PromiseResult::Successful(resp.clone()));
    assert!(!c.on_signature(U64(2), Ok(serde_json::from_slice(&resp).unwrap())));
    assert!(matches!(c.leg, Leg::SignatureRequested { .. }));
}

#[test]
fn fee_bump_after_signed_is_allowed() {
    let k = test_key(7);
    let mut c = contract_with_derived(&k);
    let tx = request(&mut c, 0);
    let resp = mock_mpc_response(&k, &tx.payload);
    set_callback_env(PromiseResult::Successful(resp.clone()));
    assert!(c.on_signature(U64(0), Ok(serde_json::from_slice(&resp).unwrap())));
    set_env(owner(), 1, 300);
    let _ = c.request_signature(U64(0), U128(60_000_000_000), U128(3_000_000_000), U64(120_000));
    match &c.leg {
        Leg::SignatureRequested { tx: bumped } => {
            assert_eq!(bumped.nonce, 0);
            assert_ne!(bumped.payload, tx.payload);
        }
        other => panic!("expected SignatureRequested, got {other:?}"),
    }
}

#[test]
fn preview_matches_request() {
    let mut c = contract_with_derived(&test_key(1));
    set_env(owner(), 0, 300);
    let preview = c.preview_tx(U64(5), U128(30_000_000_000), U128(1_500_000_000), U64(120_000));
    let tx = request(&mut c, 5);
    assert_eq!(preview.payload, to_hex(&tx.payload));
}
